CREATE TABLE IF NOT EXISTS "routing_governance_states" ("id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "subject_type" TEXT NOT NULL, "subject_id" INTEGER NOT NULL, "model_name" TEXT NOT NULL DEFAULT '', "state" TEXT NOT NULL DEFAULT 'suppressed', "reason_code" TEXT NOT NULL, "reason_detail" TEXT, "probe_model_name" TEXT, "last_http_status" INTEGER, "failure_count" INTEGER NOT NULL DEFAULT 0, "success_count" INTEGER NOT NULL DEFAULT 0, "suppress_until" TEXT, "probe_after" TEXT, "last_failure_at" TEXT, "last_success_at" TEXT, "last_probe_at" TEXT, "last_probe_status" TEXT, "last_probe_message" TEXT, "created_at" TEXT NOT NULL DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'), "updated_at" TEXT NOT NULL DEFAULT to_char(timezone('UTC', CURRENT_TIMESTAMP), 'YYYY-MM-DD HH24:MI:SS'));
CREATE UNIQUE INDEX "routing_governance_states_subject_scope_unique" ON "routing_governance_states" ("subject_type", "subject_id", "model_name");
CREATE INDEX "routing_governance_states_reason_state_idx" ON "routing_governance_states" ("reason_code", "state");
CREATE INDEX "routing_governance_states_state_suppress_idx" ON "routing_governance_states" ("state", "suppress_until", "probe_after");
CREATE INDEX "routing_governance_states_subject_idx" ON "routing_governance_states" ("subject_type", "subject_id");
